const DOJO_KUN=[
 {jp:'一、吾々は心身を錬磨し、確固不抜の心技を極めること。',reading:'ひとつ、われわれは、しんしんをれんまし、かっこふばつのしんぎをきわめること。',romaji:'Hitotsu, wareware wa shinshin o renma shi, kakko fubatsu no shingi o kiwameru koto.',pt:"Treinaremos firmemente nosso coração e nosso corpo, para termos um espírito inabalável."},
 {jp:'一、吾々は武の神髄を極め、機に発し感に敏なること。',reading:'ひとつ、われわれは、ぶのしんずいをきわめ、きにはっし、かんにびんなること。',romaji:'Hitotsu, wareware wa bu no shinzui o kiwame, ki ni hasshi, kan ni bin naru koto.',pt:"Alimentaremos a verdadeira significação da arte marcial do karate, para que no devido tempo nossos sentidos possam atuar melhor."},
 {jp:'一、吾々は質実剛健を以って、克己の精神を涵養すること。',reading:'ひとつ、われわれは、しつじつごうけんをもって、こっきのせいしんをかんようすること。',romaji:'Hitotsu, wareware wa shitsujitsu gōken o motte, kokki no seishin o kan’yō suru koto.',pt:"Com verdadeiro vigor procuraremos cultivar o espírito da abnegação."},
 {jp:'一、吾々は礼節を重んじ長上を敬し、粗暴の振舞いを慎むこと。',reading:'ひとつ、われわれは、れいせつをおもんじ、ちょうじょうをけいし、そぼうのふるまいをつつしむこと。',romaji:'Hitotsu, wareware wa reisetsu o omonji, chōjō o keishi, sobō no furumai o tsutsushimu koto.',pt:"Observaremos as regras de cortesia, respeito aos nossos superiores e nos absteremos da violência."},
 {jp:'一、吾々は神仏を尊び、謙譲の美徳を忘れざること。',reading:'ひとつ、われわれは、しんぶつをとうとび、けんじょうのびとくをわすれざること。',romaji:'Hitotsu, wareware wa shinbutsu o tōtobi, kenjō no bitoku o wasurezaru koto.',pt:"Seguiremos nosso Deus e eternas verdades e jamais esqueceremos a verdadeira virtude da humildade."},
 {jp:'一、吾々は知性と体力とを向上させ、事に臨んで過たざること。',reading:'ひとつ、われわれは、ちせいとたいりょくとをこうじょうさせ、ことにのぞんであやまたざること。',romaji:'Hitotsu, wareware wa chisei to tairyoku to o kōjō sase, koto ni nozonde ayamatazaru koto.',pt:"Olharemos para o alto, para a sabedoria e para o poder, não procurando outros desejos."},
 {jp:'一、吾々は生涯の修行を空手の道に通じ、極真の道を全うすること。',reading:'ひとつ、われわれは、しょうがいのしゅぎょうをからてのみちにつうじ、きょくしんのみちをまっとうすること。',romaji:'Hitotsu, wareware wa shōgai no shugyō o karate no michi ni tsūji, kyokushin no michi o mattō suru koto.',pt:"Em toda nossa vida, através da disciplina do karate, procuraremos preencher a verdadeira significação da filosofia da vida."}
].map((item,i)=>({...item,id:i+1,jaKey:'Juramento '+(i+1)+' em japonês',ptKey:'Juramento '+(i+1)+' em português'}));
function oathButtons(jaKey,ptKey){return `<div class="audio-buttons"><button type="button" class="audio" data-speak="${jaKey}">◖)) Japonês</button><button type="button" class="audio slow-audio" data-speak="${jaKey}" data-slow>0,7× · Devagar</button><button type="button" class="audio" data-speak="${ptKey}">◖)) Português</button></div>`;}
function dojoKunWords(){return `<section class="words-section" id="words-dojo-kun"><div class="section-head"><h2>Dojo Kun · O juramento do dojo</h2><span class="tiny">7 COMPROMISSOS</span></div><p>Leia um compromisso por vez, escute e repita com seu sensei.</p><div class="info-panel oath-whole"><h3>Ouvir o juramento completo</h3>${oathButtons('Juramento completo em japonês','Juramento completo em português')}</div><div class="oath-list">${DOJO_KUN.map(v=>`<article class="info-panel oath-card"><span class="eyebrow">COMPROMISSO ${v.id}</span><h3 lang="pt-BR">${esc(v.pt)}</h3><p class="oath-japanese" lang="ja">${v.jp}</p><p class="oath-romaji">${v.romaji}</p>${oathButtons(v.jaKey,v.ptKey)}</article>`).join('')}</div><p class="week-note">Japonês tradicional e romaji para acompanhar a leitura. Texto em português adotado pelo San Dojo. Áudios sintetizados em japonês e português.</p><a class="external-video" href="https://www.shinkyokushinkai.co.jp/soshiki/motto/" target="_blank" rel="noopener">Fonte: Dojo Kun da Shinkyokushinkai ↗</a><a class="external-video" href="https://branch.kyokushinkaikan.org/yamaguchi/wp-content/uploads/sites/101/2016/02/2b82335f635a945c051d3648bd082ce4.pdf" target="_blank" rel="noopener">Referência complementar do texto japonês ↗</a></section>`;}
function kataWords(){return `<section class="words-section" id="words-katas"><div class="section-head"><h2>Pronúncia dos 23 katas</h2><span class="tiny">OUÇA E REPITA</span></div><p>O nome em letras comuns ajuda a acompanhar o áudio japonês. Toque em Devagar para repetir no seu ritmo.</p><div class="word-grid">${KATA_CATALOG.map(k=>`<article class="word-card kata-word-card"><small>${esc(k.family)}</small><div class="japanese" lang="ja">${k.jp}</div><h3>${esc(k.name)}</h3>${audioButtons(k.name)}<button type="button" class="text-button" data-kata="${k.id}">Ver material do kata →</button></article>`).join('')}</div></section>`;}
